// Jefe 1: Gólem de piedra gigante (3×3). El más grande del set.
// Cuerpo de bloque macizo, brazos de bloque, cabeza rectangular con boca,
// ojos de latón y grietas. La ropa usa la rampa del bando (w W o O b).

pal({
  k: "#2a2233", w: "#f8f0dc", W: "#e8d5ac", o: "#c9a468", O: "#9a7440", b: "#6b4d2c",
  p: "#a48fce", P: "#7d63b0", q: "#5a4487", Q: "#3a2a5c",
  t: "#a8e8cd", T: "#5ec3a4", u: "#338f77", U: "#1f6152",
  s: "#f1c5a0", S: "#c98e6c",
  m: "#d6dde6", M: "#8a95a5",
  n: "#9a6a3e", N: "#5e3c22",
  g: "#e9e6df", G: "#a9a49a",
  y: "#f0c85a", Y: "#b08530",
  f: "#9fe3ff", F: "#4aa8d8",
  e: "#ffb347"
});
ramps("bOoWw", "QqPp", "UuTt", "SsS", "MmM", "Yy");

const DARK = { w: "p", W: "P", o: "q", O: "Q", b: "Q" };
const WILD = { w: "t", W: "T", o: "u", O: "U", b: "U" };

const piece = (name, art) => {
  sprite("_" + name, art);
  sprite(name + "_l", { base: "_" + name, outline: "k" });
  sprite(name + "_d", { base: "_" + name, swap: DARK, outline: "k" });
  sprite(name + "_w", { base: "_" + name, swap: WILD, outline: "k" });
};

